111	function listAgents(dir) {
112	  try {
113	    if (!fs.existsSync(dir)) return [];
114	    return fs.readdirSync(dir)
115	      .filter(f => f.endsWith('.md'))
116	      .map(f => parseAgent(path.join(dir, f)))
117	      .filter(Boolean);
118	  } catch {
