123	function listMdFiles(dir) {
124	  try {
125	    if (!fs.existsSync(dir)) return [];
126	    return fs.readdirSync(dir)
127	      .filter(f => f.endsWith('.md'))
128	      .map(f => {
129	        const filePath = path.join(dir, f);
130	        const content = readFileSafe(filePath);
131	        const stats = fs.statSync(filePath);
132	        return {
133	          name: f.replace('.md', ''),
134	          content: content || '',
135	          path: filePath,
136	          updatedAt: stats.mtime.toISOString(),
137	        };
138	      });
139	  } catch {
140	    return [];
141	  }
142	}
