353	// --- Directory Browser ---
354	app.get('/api/browse', (req, res) => {
355	  let targetPath = (req.query.path || HOME).replace(/^~/, HOME);
356	  targetPath = path.resolve(targetPath);
357	
358	  try {
359	    if (!fs.existsSync(targetPath)) {
360	      return res.status(404).json({ error: 'Path not found' });
361	    }
362	    const stat = fs.statSync(targetPath);
363	    if (!stat.isDirectory()) {
364	      return res.status(400).json({ error: 'Not a directory' });
365	    }
366	
367	    const entries = fs.readdirSync(targetPath, { withFileTypes: true });
368	    const dirs = entries
369	      .filter(e => e.isDirectory() && !e.name.startsWith('.') && e.name !== 'node_modules' && e.name !== '__pycache__')
370	      .map(e => ({
371	        name: e.name,
372	        path: path.join(targetPath, e.name),
373	        displayPath: path.join(targetPath, e.name).replace(HOME, '~'),
374	        hasProjects: false,
375	      }))
376	      .sort((a, b) => a.name.localeCompare(b.name));
377	
378	    for (const dir of dirs) {
379	      try {
380	        const sub = fs.readdirSync(dir.path, { withFileTypes: true });
381	        dir.hasProjects = sub.some(s =>
382	          s.isDirectory() && (
383	            fs.existsSync(path.join(dir.path, s.name, '.claude')) ||
384	            fs.existsSync(path.join(dir.path, s.name, 'CLAUDE.md')) ||
385	            fs.existsSync(path.join(dir.path, s.name, 'package.json')) ||
386	            fs.existsSync(path.join(dir.path, s.name, 'pubspec.yaml'))
387	          )
388	        );
389	      } catch {}
390	    }
391	
392	    const parts = targetPath.split(path.sep).filter(Boolean);
393	    const breadcrumbs = parts.map((part, i) => ({
394	      name: i === 0 && targetPath.startsWith(HOME) ? '~' : part,
395	      path: path.sep + parts.slice(0, i + 1).join(path.sep),
396	    }));
397	
398	    if (targetPath.startsWith(HOME)) {
399	      const homeIndex = HOME.split(path.sep).filter(Boolean).length - 1;
400	      breadcrumbs.splice(0, homeIndex + 1, { name: '~', path: HOME });
401	    }
402	
403	    res.json({
404	      current: targetPath,
405	      displayPath: targetPath.replace(HOME, '~'),
406	      parent: path.dirname(targetPath) !== targetPath ? path.dirname(targetPath) : null,
407	      breadcrumbs,
408	      directories: dirs,
409	    });
410	  } catch (e) {
411	    res.status(500).json({ error: 'Cannot read directory' });
412	  }
413	});
