470	app.post('/api/copy-agent', (req, res) => {
471	  const { from, to, agentName } = req.body;
472	  if (!isValidName(agentName)) return res.status(400).json({ error: 'Invalid agent name' });
473	
474	  let srcPath, destDir;
475	  if (from === 'global') {
476	    srcPath = path.join(CLAUDE_DIR, 'agents', agentName + '.md');
