813	function runClaudeSync(prompt, timeoutMs = 120000) {
814	  return new Promise((resolve, reject) => {
815	    const claudePath = process.env.CLAUDE_PATH || 'claude';
816	    const childEnv = { ...process.env, HOME: os.homedir() };
817	    delete childEnv.CLAUDECODE;
818	    const proc = spawn(claudePath, ['-p'], { env: childEnv });
819	    let out = '', err = '';
820	    let killed = false;
821	
822	    const timer = setTimeout(() => {
823	      killed = true;
824	      proc.kill('SIGTERM');
825	      setTimeout(() => { try { proc.kill('SIGKILL'); } catch {} }, 5000);
826	    }, timeoutMs);
827	
828	    proc.stdout.on('data', d => { out += d.toString(); });
829	    proc.stderr.on('data', d => { err += d.toString(); });
830	    proc.on('close', code => {
831	      clearTimeout(timer);
832	      if (killed) reject(new Error(`Node execution timed out after ${timeoutMs / 1000}s`));
833	      else if (code !== 0) reject(new Error(err.trim() || `claude exited ${code}`));
834	      else resolve(out.trim());
835	    });
836	    proc.on('error', (e) => { clearTimeout(timer); reject(e); });
837	    proc.stdin.write(prompt, 'utf8');
838	    proc.stdin.end();
839	  });
