import { useState } from 'react'
import {
  CheckCircle,
  XCircle,
  AlertCircle,
  RefreshCw,
  Wrench,
  Package,
  Bot,
  Zap,
  Terminal,
  Code,
} from 'lucide-react'
import { useApi } from '../hooks/useApi'
import { toast } from '../components/Toast'

interface SetupStatus {
  pm2Status: string
  launchAgentInstalled: boolean
  agentCount: number
  sdkExists: boolean
  port: number
}

interface SetupProject {
  name: string
  path: string
  hasSdk: boolean
  hasPackageEntry: boolean
}

const getSetupStatus = () =>
  fetch('/api/setup/status').then((r) => r.json() as Promise<SetupStatus>)

const getSetupProjects = () =>
  fetch('/api/setup/projects').then((r) => r.json() as Promise<SetupProject[]>)

function StatusBadge({ ok, label }: { ok: boolean; label: string }) {
  return (
    <span
      className={`inline-flex items-center gap-1.5 text-xs font-medium px-2.5 py-1 rounded-full ${
        ok
          ? 'bg-green-muted text-green border border-green/20'
          : 'bg-red-muted text-red border border-red/20'
      }`}
    >
      {ok ? <CheckCircle className="w-3 h-3" /> : <XCircle className="w-3 h-3" />}
      {label}
    </span>
  )
}

function StatusCard({
  icon: Icon,
  title,
  status,
  statusLabel,
  detail,
  action,
}: {
  icon: React.ComponentType<{ className?: string }>
  title: string
  status: 'ok' | 'warn' | 'error'
  statusLabel: string
  detail?: string
  action?: React.ReactNode
}) {
  const colors = {
    ok: { dot: 'bg-green', ring: 'border-green/20', bg: 'bg-green-muted', text: 'text-green' },
    warn: { dot: 'bg-amber', ring: 'border-amber/20', bg: 'bg-amber-muted', text: 'text-amber' },
    error: { dot: 'bg-red', ring: 'border-red/20', bg: 'bg-red-muted', text: 'text-red' },
  }
  const c = colors[status]

  return (
    <div className="bg-surface border border-border rounded-xl p-5 flex items-start gap-4">
      <div className={`p-2.5 rounded-lg ${c.bg} ${c.text} shrink-0`}>
        <Icon className="w-5 h-5" />
      </div>
      <div className="flex-1 min-w-0">
        <div className="flex items-center justify-between gap-4">
          <p className="text-sm font-medium">{title}</p>
          <span
            className={`inline-flex items-center gap-1.5 text-xs font-medium px-2.5 py-1 rounded-full border ${c.bg} ${c.text} ${c.ring} shrink-0`}
          >
            <span className={`w-1.5 h-1.5 rounded-full ${c.dot}`} />
            {statusLabel}
          </span>
        </div>
        {detail && <p className="text-xs text-text-muted mt-1">{detail}</p>}
        {action && <div className="mt-3">{action}</div>}
      </div>
    </div>
  )
}

function CodeBlock({ code, lang = 'bash' }: { code: string; lang?: string }) {
  const [copied, setCopied] = useState(false)

  const handleCopy = () => {
    navigator.clipboard.writeText(code).then(() => {
      setCopied(true)
      setTimeout(() => setCopied(false), 2000)
    })
  }

  return (
    <div className="relative group">
      <pre className="bg-bg border border-border rounded-lg p-4 text-xs font-mono text-text-muted overflow-x-auto leading-relaxed">
        <code>{code}</code>
      </pre>
      <button
        onClick={handleCopy}
        className="absolute top-2.5 right-2.5 px-2 py-1 text-[10px] font-medium bg-surface border border-border rounded text-text-muted hover:text-text transition-colors opacity-0 group-hover:opacity-100"
      >
        {copied ? 'Copied!' : 'Copy'}
      </button>
      {lang && (
        <span className="absolute bottom-2.5 right-2.5 text-[10px] text-text-muted opacity-50 font-mono">
          {lang}
        </span>
      )}
    </div>
  )
}

export default function Setup() {
  const { data: status, loading: statusLoading, refetch: refetchStatus } = useApi(getSetupStatus)
  const { data: projects, loading: projectsLoading, refetch: refetchProjects } = useApi(getSetupProjects)
  const [installingPaths, setInstallingPaths] = useState<Set<string>>(new Set())

  const pm2StatusMap: Record<string, { label: string; status: 'ok' | 'warn' | 'error' }> = {
    online: { label: 'Running', status: 'ok' },
    stopped: { label: 'Stopped', status: 'warn' },
    errored: { label: 'Errored', status: 'error' },
    not_registered: { label: 'Not Registered', status: 'warn' },
    not_installed: { label: 'Not Installed', status: 'error' },
    unknown: { label: 'Unknown', status: 'warn' },
  }

  const pm2Info = pm2StatusMap[status?.pm2Status ?? 'unknown'] ?? { label: status?.pm2Status ?? 'Unknown', status: 'warn' as const }

  async function handleInstallSdk(projectPath: string) {
    setInstallingPaths((prev) => new Set(prev).add(projectPath))
    try {
      const res = await fetch('/api/setup/install-sdk', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ projectPath }),
      })
      const data = await res.json()
      if (!res.ok) throw new Error(data.error || 'Install failed')
      toast('success', `SDK installed in ${projectPath.split('/').pop()}`)
      refetchProjects()
    } catch (err) {
      toast('error', err instanceof Error ? err.message : 'Install failed')
    } finally {
      setInstallingPaths((prev) => {
        const next = new Set(prev)
        next.delete(projectPath)
        return next
      })
    }
  }

  return (
    <div className="p-8 max-w-4xl">
      {/* Header */}
      <div className="mb-8">
        <div className="flex items-center gap-3 mb-2">
          <div className="p-2 bg-accent-muted rounded-lg">
            <Wrench className="w-5 h-5 text-accent" />
          </div>
          <h1 className="text-2xl font-semibold tracking-tight">Setup & Status</h1>
        </div>
        <p className="text-text-muted text-sm">
          System health, SDK installation, and quick reference for agents and commands.
        </p>
      </div>

      {/* Section 1: System Health */}
      <section className="mb-10">
        <div className="flex items-center justify-between mb-4">
          <h2 className="text-sm font-semibold uppercase tracking-wider text-text-muted">
            System Health
          </h2>
          <button
            onClick={() => { refetchStatus(); refetchProjects(); }}
            className="flex items-center gap-1.5 text-xs text-text-muted hover:text-text transition-colors"
          >
            <RefreshCw className="w-3.5 h-3.5" />
            Refresh
          </button>
        </div>

        {statusLoading ? (
          <div className="grid grid-cols-2 gap-4">
            {Array.from({ length: 4 }).map((_, i) => (
              <div key={i} className="h-24 bg-surface border border-border rounded-xl animate-pulse" />
            ))}
          </div>
        ) : (
          <div className="grid grid-cols-2 gap-4">
            <StatusCard
              icon={Zap}
              title="Claude Hub Service"
              status={pm2Info.status}
              statusLabel={pm2Info.label}
              detail={status ? `Port ${status.port}` : undefined}
              action={
                status?.pm2Status !== 'online' ? (
                  <CodeBlock code="pm2 restart claude-hub" />
                ) : undefined
              }
            />
            <StatusCard
              icon={RefreshCw}
              title="Auto-Start on Login"
              status={status?.launchAgentInstalled ? 'ok' : 'error'}
              statusLabel={status?.launchAgentInstalled ? 'Enabled' : 'Not Configured'}
              detail={
                status?.launchAgentInstalled
                  ? '~/Library/LaunchAgents/io.boldteq.claude-hub.plist'
                  : 'LaunchAgent not found — Claude Hub will not start on login'
              }
              action={
                !status?.launchAgentInstalled ? (
                  <CodeBlock code="launchctl load ~/Library/LaunchAgents/io.boldteq.claude-hub.plist" />
                ) : undefined
              }
            />
            <StatusCard
              icon={Bot}
              title="Global Agents"
              status={(status?.agentCount ?? 0) > 0 ? 'ok' : 'error'}
              statusLabel={
                (status?.agentCount ?? 0) > 0
                  ? `${status?.agentCount} agents loaded`
                  : 'No agents found'
              }
              detail="~/.claude/agents/"
            />
            <StatusCard
              icon={Package}
              title="Agent SDK"
              status={status?.sdkExists ? 'ok' : 'error'}
              statusLabel={status?.sdkExists ? 'Ready' : 'Missing'}
              detail="claude-hub/sdk/package.json"
            />
          </div>
        )}
      </section>

      {/* Section 2: Project SDK Status */}
      <section className="mb-10">
        <h2 className="text-sm font-semibold uppercase tracking-wider text-text-muted mb-4">
          Project SDK Status
        </h2>

        {projectsLoading ? (
          <div className="bg-surface border border-border rounded-xl p-6 animate-pulse h-40" />
        ) : !projects || projects.length === 0 ? (
          <div className="bg-surface border border-border rounded-xl p-6 text-center text-text-muted text-sm">
            No projects found. Add project directories in Settings.
          </div>
        ) : (
          <div className="bg-surface border border-border rounded-xl overflow-hidden">
            <table className="w-full text-sm">
              <thead>
                <tr className="border-b border-border">
                  <th className="text-left px-5 py-3 text-xs font-semibold text-text-muted uppercase tracking-wider">
                    Project
                  </th>
                  <th className="text-center px-4 py-3 text-xs font-semibold text-text-muted uppercase tracking-wider">
                    SDK Installed
                  </th>
                  <th className="text-center px-4 py-3 text-xs font-semibold text-text-muted uppercase tracking-wider">
                    package.json Entry
                  </th>
                  <th className="px-4 py-3" />
                </tr>
              </thead>
              <tbody>
                {projects.map((p, i) => {
                  const isInstalling = installingPaths.has(p.path)
                  const needsInstall = !p.hasSdk || !p.hasPackageEntry
                  return (
                    <tr
                      key={p.path}
                      className={`${i < projects.length - 1 ? 'border-b border-border' : ''} hover:bg-surface-2 transition-colors`}
                    >
                      <td className="px-5 py-3">
                        <p className="font-medium">{p.name}</p>
                        <p className="text-xs text-text-muted mt-0.5">
                          {p.path.replace('/Users/yashbaldha', '~')}
                        </p>
                      </td>
                      <td className="px-4 py-3 text-center">
                        <StatusBadge ok={p.hasSdk} label={p.hasSdk ? 'Installed' : 'Missing'} />
                      </td>
                      <td className="px-4 py-3 text-center">
                        <StatusBadge ok={p.hasPackageEntry} label={p.hasPackageEntry ? 'Yes' : 'No'} />
                      </td>
                      <td className="px-4 py-3 text-right">
                        {needsInstall && (
                          <button
                            disabled={isInstalling}
                            onClick={() => handleInstallSdk(p.path)}
                            className="inline-flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium bg-accent text-white rounded-lg hover:opacity-90 transition-opacity disabled:opacity-50 disabled:cursor-not-allowed"
                          >
                            {isInstalling ? (
                              <>
                                <RefreshCw className="w-3 h-3 animate-spin" />
                                Installing...
                              </>
                            ) : (
                              <>
                                <Package className="w-3 h-3" />
                                Install
                              </>
                            )}
                          </button>
                        )}
                      </td>
                    </tr>
                  )
                })}
              </tbody>
            </table>
          </div>
        )}
      </section>

      {/* Section 3: Quick Reference — How to Use Agents */}
      <section className="mb-10">
        <div className="flex items-center gap-2 mb-4">
          <Code className="w-4 h-4 text-text-muted" />
          <h2 className="text-sm font-semibold uppercase tracking-wider text-text-muted">
            How to Use Agents
          </h2>
        </div>

        <div className="bg-surface border border-border rounded-xl p-6 space-y-5">
          <div>
            <p className="text-xs font-medium text-text-muted uppercase tracking-wider mb-3">
              In any project server file
            </p>
            <CodeBlock
              lang="typescript"
              code={`import { callAgent } from '@boldteq/agents'

const result = await callAgent('quill', 'Write App Store listing for Pinzo')
console.log(result.output)`}
            />
          </div>

          <div>
            <p className="text-xs font-medium text-text-muted uppercase tracking-wider mb-3">
              Available agents
            </p>
            <div className="flex flex-wrap gap-2">
              {['quill', 'nova', 'koda', 'vex', 'sage', 'luna', 'arya', 'bolt', 'mira', 'riko', 'rex', 'hawk'].map(
                (agent) => (
                  <code
                    key={agent}
                    className="text-xs font-mono bg-bg border border-border px-2.5 py-1 rounded text-accent"
                  >
                    {agent}
                  </code>
                )
              )}
            </div>
          </div>
        </div>
      </section>

      {/* Section 4: pm2 Commands Reference */}
      <section>
        <div className="flex items-center gap-2 mb-4">
          <Terminal className="w-4 h-4 text-text-muted" />
          <h2 className="text-sm font-semibold uppercase tracking-wider text-text-muted">
            pm2 Commands
          </h2>
        </div>

        <div className="bg-surface border border-border rounded-xl p-6">
          <CodeBlock
            lang="bash"
            code={`pm2 status              # Check Claude Hub is running
pm2 restart claude-hub  # Restart
pm2 logs claude-hub     # View logs
pm2 stop claude-hub     # Stop`}
          />
        </div>
      </section>
    </div>
  )
}

